# @CMD@ shell integration for bash.
# Generated by `@CMD@ hook bash`; safe to source more than once.
# Defines a `@CMD@` function (so `@CMD@ profile use` can change this session)
# and a PROMPT_COMMAND hook that applies directory-bound profiles after `cd`.

@FN@_bin=@BIN@
@FN@_last=
@FN@_indicator=@INDICATOR@
@FN@_seg=
export @ENV_SHELL@=bash

# Tool shims (claude, codex, gh, ...) go first on PATH.
@FN@_shims=@SHIMS@
if command -v cygpath >/dev/null 2>&1; then @FN@_shims="$(cygpath -u "$@FN@_shims")"; fi
case ":$PATH:" in
  *":$@FN@_shims:"*) ;;
  *) export PATH="$@FN@_shims:$PATH" ;;
esac

@FN@_sync() {
  if [[ "$1" != force && "$PWD" == "$@FN@_last" ]]; then return 0; fi
  @FN@_last="$PWD"
  local __code
  __code="$("$@FN@_bin" hook-env --shell bash)" || return 0
  if [[ "$__code" == "@MARKER@"* ]]; then eval "$__code"; fi
  return 0
}

@FN@_prompt() {
  local __status=$?
  @FN@_sync
  if [[ "$@FN@_indicator" == 1 ]]; then
    local __seg=
    if [[ -n "$@ENV_ACTIVE@" && "$@ENV_PROMPT@" != 0 ]]; then
      __seg="\[\e[38;5;111m\][$@ENV_ACTIVE@]\[\e[0m\] "
    fi
    PS1="$__seg${PS1#"$@FN@_seg"}"
    @FN@_seg="$__seg"
  fi
  return $__status
}

@CMD@() {
  if [[ "$1" == profile && "$2" == use ]]; then
    shift 2
    local __out __status
    __out="$("$@FN@_bin" profile use "$@" --emit bash)"
    __status=$?
    if [[ $__status -eq 0 && "$__out" == "@MARKER@"* ]]; then
      eval "$__out"
    elif [[ -n "$__out" ]]; then
      printf '%s\n' "$__out"
    fi
    @FN@_sync force
    return $__status
  fi
  "$@FN@_bin" "$@"
  local __status=$?
  @FN@_sync force
  return $__status
}

if [[ "$(declare -p PROMPT_COMMAND 2>/dev/null)" == "declare -a"* ]]; then
  if [[ " ${PROMPT_COMMAND[*]} " != *" @FN@_prompt "* ]]; then
    PROMPT_COMMAND=(@FN@_prompt "${PROMPT_COMMAND[@]}")
  fi
else
  case ";${PROMPT_COMMAND:-};" in
    *";@FN@_prompt;"*) ;;
    *) PROMPT_COMMAND="@FN@_prompt${PROMPT_COMMAND:+;$PROMPT_COMMAND}" ;;
  esac
fi

@FN@_sync force
